// بيلقط كود الدكتور DV-XXXX أو كلمة إلغاء من رسالة واردة
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const d = b.data ?? {};
  if (d.key?.fromMe) continue;
  const m = d.message?.ephemeralMessage?.message ?? d.message ?? {};
  const text = m.conversation ?? m.extendedTextMessage?.text ?? '';
  const phone = String(d.key?.remoteJid ?? '').split('@')[0];
  const code = (text.match(/DV-[A-Z0-9]{4}/i) ?? [])[0];
  const stop = /^\s*(إلغاء|الغاء|stop)\s*$/i.test(text);
  if (code) out.push({ json: { action: 'qr_event', body: { code: code.toUpperCase(), phone, message: text, received_at: new Date().toISOString().slice(0, 19).replace('T', ' ') } } });
  else if (stop) out.push({ json: { action: 'opt_out', body: { phone } } });
}
return out;
